import {useEffect,useState} from 'react';
import {FileText,Loader2,RefreshCw} from 'lucide-react';
import {amendSessionNote,createPrivateNote,createSessionNote,finaliseSessionNote,getSessionNote,listPrivateNotes,listSessionNotes,saveSessionNote} from '../../lib/practiceOperationsApi';

export function PrivateNotePanel({noteId,enabled}){const [items,setItems]=useState([]);const [content,setContent]=useState('');const [error,setError]=useState('');const load=async()=>{if(!enabled)return;try{const result=await listPrivateNotes(noteId);setItems(result.items||[])}catch(reason){setError(reason.message||'Private notes could not load.')}};useEffect(()=>{void load()},[noteId,enabled]);if(!enabled)return null;const add=async()=>{if(!content.trim())return;try{await createPrivateNote(noteId,{content});setContent('');await load()}catch(reason){setError(reason.message||'Private note could not be saved.')}};return <section className="rounded-2xl border border-violet-200 bg-violet-50 p-5"><h4 className="font-bold text-violet-950">Private notes</h4><p className="mt-1 text-xs text-violet-800">Encrypted at rest and visible only when the PRIVATE_NOTES capability is enabled.</p>{error&&<p role="alert" className="mt-2 text-sm text-red-700">{error}</p>}<textarea aria-label="Private note" value={content} onChange={event=>setContent(event.target.value)} rows={3} className="mt-4 w-full rounded-xl border border-violet-200 p-3"/><button onClick={add} className="mt-2 min-h-11 rounded-xl bg-violet-900 px-4 font-semibold text-white">Add private note</button><div className="mt-4 space-y-2">{items.map(item=><article key={item.id} className="rounded-xl bg-white p-3 text-sm"><p className="whitespace-pre-wrap">{item.content}</p><small className="mt-2 block text-slate-500">{new Date(item.created_at).toLocaleString()}</small></article>)}</div></section>}

export function StructuredNoteEditor({detail,privateEnabled,onReload}){const [title,setTitle]=useState(detail.note.title);const [summary,setSummary]=useState(detail.sections.find(item=>item.section_key==='session_summary')?.content?.text||'');const [instructions,setInstructions]=useState(detail.sections.find(item=>item.section_key==='client_instructions')?.content?.text||'');const [reason,setReason]=useState('');const [busy,setBusy]=useState('');const [error,setError]=useState('');const final=detail.note.status==='FINALISED'||detail.note.status==='AMENDED';const sections=[{key:'session_summary',title:'Session summary',content:{text:summary},visibility:'PRACTITIONER'},{key:'client_instructions',title:'Client-visible instructions',content:{text:instructions},visibility:'CLIENT_INSTRUCTION'}];const run=async action=>{setBusy(action);setError('');try{if(action==='save')await saveSessionNote(detail.note.id,{title,expected_version:detail.note.current_version,sections});if(action==='finalise')await finaliseSessionNote(detail.note.id);if(action==='amend')await amendSessionNote(detail.note.id,{title,reason,sections});await onReload(detail.note.id)}catch(value){setError(value.message||'Note action failed.')}finally{setBusy('')}};return <div className="space-y-4"><section className="rounded-2xl border bg-white p-5"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-wider text-blue-700">Structured session note</p><h4 className="mt-1 text-xl font-bold">Version {detail.note.current_version} · {detail.note.status}</h4></div><div className="flex flex-wrap gap-2">{!final&&<><button disabled={busy} onClick={()=>run('save')} className="min-h-11 rounded-xl border px-4 font-semibold">Save</button><button disabled={busy} onClick={()=>run('finalise')} className="min-h-11 rounded-xl bg-slate-950 px-4 font-semibold text-white">Finalise</button></>}{final&&<button disabled={busy||reason.trim().length<3} onClick={()=>run('amend')} className="min-h-11 rounded-xl bg-slate-950 px-4 font-semibold text-white disabled:opacity-40">Create amendment</button>}</div></div>{error&&<p role="alert" className="mt-3 text-sm text-red-700">{error}</p>}<label className="mt-5 block text-sm font-semibold">Title<input value={title} onChange={event=>setTitle(event.target.value)} className="mt-2 min-h-12 w-full rounded-xl border px-3"/></label><label className="mt-4 block text-sm font-semibold">Practitioner session summary<textarea value={summary} onChange={event=>setSummary(event.target.value)} rows={5} className="mt-2 w-full rounded-xl border p-3"/></label><label className="mt-4 block text-sm font-semibold">Client-visible instructions<textarea value={instructions} onChange={event=>setInstructions(event.target.value)} rows={4} className="mt-2 w-full rounded-xl border p-3"/></label>{final&&<label className="mt-4 block text-sm font-semibold">Amendment reason<textarea value={reason} onChange={event=>setReason(event.target.value)} className="mt-2 w-full rounded-xl border p-3"/></label>}<p className="mt-3 text-xs text-slate-500">Finalised versions are immutable. Amendments create a new historical version.</p></section><PrivateNotePanel noteId={detail.note.id} enabled={privateEnabled}/></div>}

export function StructuredNotes({clientId,privateEnabled=false}){const [items,setItems]=useState([]);const [detail,setDetail]=useState(null);const [state,setState]=useState('loading');const [error,setError]=useState('');const load=async openId=>{setState('loading');setError('');try{const result=await listSessionNotes(clientId);setItems(result.items||[]);const id=openId||detail?.note?.id;if(id)setDetail(await getSessionNote(id));setState('ready')}catch(reason){setError(reason.message||'Session notes could not load.');setState('error')}};useEffect(()=>{void load()},[clientId]);const create=async()=>{try{const result=await createSessionNote({client_id:clientId,note_type:'SESSION_NOTE',title:'Session note',sections:[{key:'session_summary',title:'Session summary',content:{text:''},visibility:'PRACTITIONER'},{key:'client_instructions',title:'Client-visible instructions',content:{text:''},visibility:'CLIENT_INSTRUCTION'}]});await load(result.id)}catch(reason){setError(reason.message||'Session note could not be created.');setState('error')}};if(state==='loading')return <div role="status" className="grid min-h-40 place-items-center rounded-2xl bg-white"><Loader2 className="animate-spin"/><span className="sr-only">Loading session notes</span></div>;if(state==='error')return <div role="alert" className="rounded-2xl bg-red-50 p-5 text-red-800">{error}<button onClick={()=>load()} className="ml-3 min-h-11 px-3 font-bold"><RefreshCw className="inline"/> Retry</button></div>;return <div className="space-y-5"><div className="flex items-center justify-between gap-3"><div><h3 className="text-xl font-bold">Structured notes</h3><p className="text-sm text-slate-500">Separate practitioner context, client instructions, and governed private notes.</p></div><button onClick={create} className="min-h-11 rounded-xl bg-blue-700 px-4 font-semibold text-white">New note</button></div>{detail?<StructuredNoteEditor key={`${detail.note.id}-${detail.note.current_version}-${detail.note.status}`} detail={detail} privateEnabled={privateEnabled} onReload={load}/>:items.length?<div className="divide-y rounded-2xl border bg-white">{items.map(item=><button key={item.id} onClick={async()=>setDetail(await getSessionNote(item.id))} className="flex min-h-16 w-full items-center justify-between p-4 text-left"><span><strong>{item.title}</strong><small className="mt-1 block text-slate-500">Version {item.current_version}</small></span><span className="text-xs font-bold text-blue-700">{item.status}</span></button>)}</div>:<div className="rounded-2xl border border-dashed bg-white p-8 text-center"><FileText className="mx-auto text-blue-700"/><h4 className="mt-3 font-semibold">No structured notes yet.</h4></div>}</div>}
